using Microsoft.EntityFrameworkCore;
using HotelOps.Api.Data;
using HotelOps.Api.Entities;
using System.Text.Json;

namespace Safety008;

internal static class Offline
{
    private static Row Row(string table,long id,string hash)=>new(table,new(StringComparer.Ordinal){[table=="dbo.reference_values"?"reference_id":"user_id"]=id.ToString()},new(){[table=="dbo.reference_values"?"reference_id":"user_id"]=id.ToString()},hash);
    private static Snapshot Base()=>new("schema",[new("dbo.reference_values",[new("reference_id","bigint",1)]),new("dbo.users",[new("user_id","bigint",1)])],[],new(){[Row("dbo.reference_values",2,"protected").Key]=Row("dbo.reference_values",2,"protected")},[]);
    private static Snapshot Current(){var b=Base();var r=Row("dbo.users",357,"owned");return b with{Rows=new(b.Rows){[r.Key]=r}};}
    private sealed class MemoryStore:ICleanupStore
    {
        internal Snapshot Current=Offline.Current();private readonly Snapshot original=Offline.Current();
        internal int Begins,Deletes,Commits,Rollbacks,Captures;internal bool FailDelete,FailCommit,FailRollback,FailPost,MutatePrecommit,MutateSelected;
        public Task Begin(){Begins++;return Task.CompletedTask;}
        public Task<Snapshot> LockedSnapshot(){Captures++;if(MutatePrecommit&&Captures==3){var r=Row("dbo.reference_values",2,"tampered");Current=Current with{Rows=new(Current.Rows){[r.Key]=r}};}if(MutateSelected&&Captures==2){var r=Row("dbo.users",357,"changed-selected");Current=Current with{Rows=new(Current.Rows){[r.Key]=r}};}return Task.FromResult(Current);}
        public Task Delete(Row r,Table t){if(FailDelete)throw new InvalidOperationException("rowcount mismatch injected");Deletes++;var copy=new Dictionary<string,Row>(Current.Rows);if(!copy.Remove(r.Key))throw new InvalidOperationException("rowcount mismatch");Current=Current with{Rows=copy};return Task.CompletedTask;}
        public Task Commit(){Commits++;if(FailCommit)throw new IOException("uncertain commit injected");return Task.CompletedTask;}
        public Task Rollback(){Rollbacks++;if(FailRollback)throw new IOException("rollback failed injected");Current=original;return Task.CompletedTask;}
        public Task<Snapshot> IndependentSnapshot(){if(FailPost)throw new IOException("postcheck failed injected");return Task.FromResult(Current);}
    }
    internal static async Task Run(string output)
    {
        Directory.CreateDirectory(output);var cases=new List<object>();var fail=0;var count=0;
        async Task Test(string name,Func<string,Task> test){var dir=Path.Combine(output,$"case_{++count:D3}");Directory.CreateDirectory(dir);try{await test(dir);cases.Add(new{name,status="PASS"});}catch(Exception e){fail++;cases.Add(new{name,status="FAIL",exceptionType=e.GetType().Name,detail=e.Message});}}
        static void Check(bool value){if(!value)throw new InvalidOperationException("Offline assertion failed");}
        var session=new Session("SAFETY008_offline_12345678","D2Aoffline0000",SqlStore.DatabaseGuid,"source");var key=new byte[32];Random.Shared.NextBytes(key);
        await Test("Malformed/wrong-marker/run/GUID/signature STOP never accepted",dir=>{
            var validator=new StopValidator(session,key);foreach(var bad in new[]{"{","null","[]","{}"})Check(!validator.Accept(bad));
            var valid=validator.Sign();foreach(var wrong in new[]{valid with{Marker="other"},valid with{Run="other"},valid with{DatabaseGuid=Guid.NewGuid().ToString()},valid with{DatabaseGuid="malformed"},valid with{SourceIdentity="other"},valid with{Signature=new string('0',64)}})Check(!validator.Accept(JsonSerializer.Serialize(wrong,Durable.Json)));return Task.CompletedTask;
        });
        await Test("Valid HMAC STOP accepted once; replay ignored",dir=>{var v=new StopValidator(session,key);var raw=JsonSerializer.Serialize(v.Sign(),Durable.Json);Check(v.Accept(raw));Check(!v.Accept(raw));return Task.CompletedTask;});
        await Test("Wrong signal does not cancel actual supervisor task",async dir=>{var j=new Durable(dir);var v=new StopValidator(session,key);using var owner=new CancellationTokenSource();if(v.Accept("{bad"))owner.Cancel();var r=await new Lifecycle(j).Supervise(_=>Task.FromResult(new ChildOutcome(ChildKind.NormalBrowserExit,0,true)),()=>true,TimeSpan.FromSeconds(1),owner.Token);Check(r.Kind==ChildKind.NormalBrowserExit);Durable.Verify(dir);});
        await Test("Child failure recorded without finally cleanup",async dir=>{var r=await new Lifecycle(new Durable(dir)).Supervise(_=>Task.FromResult(new ChildOutcome(ChildKind.Failure,1,true)),()=>true,TimeSpan.FromSeconds(1),CancellationToken.None);Check(r.Kind==ChildKind.Failure&&r.NativeExit==1);});
        await Test("Controller interruption cooperatively quiesces child; no cleanup callback",async dir=>{var calls=0;var r=await new Lifecycle(new Durable(dir)).Supervise(async ct=>{try{await Task.Delay(5000,ct);}catch(OperationCanceledException){}return new(ChildKind.ControllerLost,0,true);},()=>++calls<3,TimeSpan.FromSeconds(2),CancellationToken.None);Check(r.Kind==ChildKind.ControllerLost&&r.Quiesced);});
        await Test("Dead controller prevents child startup",async dir=>{var started=false;var r=await new Lifecycle(new Durable(dir)).Supervise(_=>{started=true;return Task.FromResult(new ChildOutcome(ChildKind.NormalBrowserExit,0,true));},()=>false,TimeSpan.FromSeconds(1),CancellationToken.None);Check(!started&&r.Kind==ChildKind.ControllerLost);});
        await Test("Timeout distinguished from normal exit and owner cancellation",async dir=>{var r=await new Lifecycle(new Durable(dir)).Supervise(async ct=>{try{await Task.Delay(5000,ct);}catch(OperationCanceledException){}return new(ChildKind.NormalBrowserExit,0,true);},()=>true,TimeSpan.FromMilliseconds(20),CancellationToken.None);Check(r.Kind==ChildKind.TimedOut);});
        await Test("Owner cancellation is explicit outcome",async dir=>{using var owner=new CancellationTokenSource(20);var r=await new Lifecycle(new Durable(dir)).Supervise(async ct=>{try{await Task.Delay(5000,ct);}catch(OperationCanceledException){}return new(ChildKind.NormalBrowserExit,0,true);},()=>true,TimeSpan.FromSeconds(2),owner.Token);Check(r.Kind==ChildKind.OwnerCancellation);});
        await Test("Hash-chained durable journal detects tampering",async dir=>{var j=new Durable(dir);await j.Event("one",new{value=1});await j.Event("two",new{value=2});Durable.Verify(dir);var copy=Path.Combine(output,"tampered-copy");Directory.CreateDirectory(copy);foreach(var f in Directory.EnumerateFiles(dir))File.Copy(f,Path.Combine(copy,Path.GetFileName(f)));var first=Directory.EnumerateFiles(copy).First();await File.WriteAllTextAsync(first,"{}");try{Durable.Verify(copy);throw new InvalidOperationException("Expected rejection");}catch(KeyNotFoundException){}catch(JsonException){} });
        await Test("Pending durable write cannot be reported complete",async dir=>{await File.WriteAllTextAsync(Path.Combine(dir,"interrupted.pending"),"partial");try{Durable.Verify(dir);throw new Exception("Expected rejection");}catch(InvalidOperationException){}});
        await Test("Original factory-added keys produce exact owned graph",dir=>{var current=Current();var seed=current.Rows.Keys.Except(Base().Rows.Keys).ToHashSet();var proof=Graph.Prove(Base(),current,seed,[],new HashSet<long>());Check(proof.Problems.Length==0&&proof.Owned.Count==1);return Task.CompletedTask;});
        await Test("Membership/branch/actor alone does not own new row",dir=>{var p=Graph.Prove(Base(),Current(),new HashSet<string>(),[],new HashSet<long>{357});Check(p.Problems.Any(p=>p.StartsWith("UNPROVEN_NEW_ROW",StringComparison.Ordinal)));return Task.CompletedTask;});
        await Test("Borrowed/shared row hash mismatch blocks cleanup",dir=>{var current=Current();var protectedRow=Row("dbo.reference_values",2,"changed");current=current with{Rows=new(current.Rows){[protectedRow.Key]=protectedRow}};Check(Graph.Prove(Base(),current,new HashSet<string>(),[],new HashSet<long>()).Problems.Any(p=>p.StartsWith("PROTECTED_ROW_CHANGED",StringComparison.Ordinal)));return Task.CompletedTask;});
        await Test("New rows not in actual seed ledger remain unknown",dir=>{Check(Graph.Prove(Base(),Current(),new HashSet<string>(),[],new HashSet<long>()).Problems.Length>0);return Task.CompletedTask;});
        await Test("Baseline row cannot be claimed by seed journal",dir=>{var b=Base();Check(Graph.Prove(b,b,b.Rows.Keys.ToHashSet(),[],new HashSet<long>()).Problems.Any(p=>p.StartsWith("SEED_SELECTS_BASELINE_ROW",StringComparison.Ordinal)));return Task.CompletedTask;});
        await Test("Unreviewed enabled trigger fails graph proof",dir=>{var b=Base();Check(Graph.Prove(b,b with{EnabledTriggers=["trigger"]},new HashSet<string>(),[],new HashSet<long>()).Problems.Contains("UNREVIEWED_DML_TRIGGER"));return Task.CompletedTask;});
        await Test("Schema drift blocks cleanup",dir=>{var b=Base();Check(Graph.Prove(b,b with{SchemaHash="different"},new HashSet<string>(),[],new HashSet<long>()).Problems.Contains("SCHEMA_DRIFT"));return Task.CompletedTask;});
        await Test("Cleanup exact-PK transaction and idempotent finalization",async dir=>{var s=new MemoryStore();var adapter=new CleanupAdapter(s,Base(),Current().Rows.Keys.Except(Base().Rows.Keys).ToHashSet(),[],new HashSet<long>(),new Durable(dir));var a=adapter.FinalizeOnce();var b=adapter.FinalizeOnce();Check(ReferenceEquals(a,b));var r=await a;Check(r.Status=="PASS_EXACT_PK_CLEANUP"&&s.Deletes==1&&s.Begins==1&&s.Commits==1);Durable.Verify(dir);});
        await Test("Wrong rowcount aborts and rolls back",async dir=>{var s=new MemoryStore{FailDelete=true};var r=await new CleanupAdapter(s,Base(),Current().Rows.Keys.Except(Base().Rows.Keys).ToHashSet(),[],new HashSet<long>(),new Durable(dir)).FinalizeOnce();Check(r.Status=="ROLLED_BACK_FAIL_CLOSED"&&s.Commits==0&&s.Rollbacks==1);});
        await Test("Protected row precommit mutation triggers full rollback",async dir=>{var s=new MemoryStore{MutatePrecommit=true};var r=await new CleanupAdapter(s,Base(),Current().Rows.Keys.Except(Base().Rows.Keys).ToHashSet(),[],new HashSet<long>(),new Durable(dir)).FinalizeOnce();Check(r.Status=="ROLLED_BACK_FAIL_CLOSED"&&s.Commits==0&&s.Rollbacks==1);});
        await Test("Selected-row mutation before delete aborts with zero deletes",async dir=>{var s=new MemoryStore{MutateSelected=true};var r=await new CleanupAdapter(s,Base(),Current().Rows.Keys.Except(Base().Rows.Keys).ToHashSet(),[],new HashSet<long>(),new Durable(dir)).FinalizeOnce();Check(r.Status=="ROLLED_BACK_FAIL_CLOSED"&&s.Deletes==0);});
        await Test("Lost controller before commit rolls back",async dir=>{var s=new MemoryStore();var r=await new CleanupAdapter(s,Base(),Current().Rows.Keys.Except(Base().Rows.Keys).ToHashSet(),[],new HashSet<long>(),new Durable(dir),()=>false).FinalizeOnce();Check(r.Status=="ROLLED_BACK_FAIL_CLOSED"&&s.Commits==0);});
        await Test("Uncertain commit never claims rollback or retries",async dir=>{var s=new MemoryStore{FailCommit=true};var a=new CleanupAdapter(s,Base(),Current().Rows.Keys.Except(Base().Rows.Keys).ToHashSet(),[],new HashSet<long>(),new Durable(dir));var r=await a.FinalizeOnce();await a.FinalizeOnce();Check(r.Status=="COMMIT_UNCERTAIN_NO_AUTOMATIC_RETRY"&&s.Rollbacks==0&&s.Commits==1);});
        await Test("Rollback failure remains uncertain",async dir=>{var s=new MemoryStore{FailDelete=true,FailRollback=true};var r=await new CleanupAdapter(s,Base(),Current().Rows.Keys.Except(Base().Rows.Keys).ToHashSet(),[],new HashSet<long>(),new Durable(dir)).FinalizeOnce();Check(r.Status=="ROLLBACK_UNCONFIRMED_RECOVERY_REQUIRED");});
        await Test("Postcommit proof failure cannot undo/claim cleanup PASS",async dir=>{var s=new MemoryStore{FailPost=true};var r=await new CleanupAdapter(s,Base(),Current().Rows.Keys.Except(Base().Rows.Keys).ToHashSet(),[],new HashSet<long>(),new Durable(dir)).FinalizeOnce();Check(r.Status=="COMMITTED_POSTCHECK_UNCERTAIN"&&r.CommitAcknowledged&&!r.IndependentPostcheck);});
        await Test("Actual EF model PK encoding without database access",dir=>{using var db=new HotelOpsDbContext(new DbContextOptionsBuilder<HotelOpsDbContext>().UseSqlServer("Server=unused;Database=unused;Integrated Security=true").Options);var user=new User{UserId=357};var entry=db.Entry(user);var pk=SeedLedger.Key(entry);Check(pk.Table=="dbo.users"&&pk.Pk["user_id"]=="357");return Task.CompletedTask;});
        await Test("Borrowed reference PK is not a polymorphic reference",dir=>{var b=Base();var r=Row("dbo.reference_values",9,"private");var c=b with{Rows=new(b.Rows){[r.Key]=r}};Check(Graph.Prove(b,c,new HashSet<string>{r.Key},[],new HashSet<long>()).Problems.Length==0);return Task.CompletedTask;});
        await Test("Exact composite keys and FK dependency order",dir=>{
            var b=Base();var parent=Row("dbo.users",357,"owned");var child=new Row("dbo.user_roles",new(){["role_id"]="109",["user_id"]="357"},new(){["role_id"]="109",["user_id"]="357"},"composite");
            var c=b with{Tables=[..b.Tables,new("dbo.user_roles",[new("user_id","bigint",1),new("role_id","bigint",2)])],ForeignKeys=[new("fk","dbo.user_roles","dbo.users",["user_id"],["user_id"],false,false,"NO_ACTION")],Rows=new(b.Rows){[parent.Key]=parent,[child.Key]=child}};var p=Graph.Prove(b,c,new HashSet<string>{parent.Key,child.Key},[],new HashSet<long>{357});Check(p.Problems.Length==0&&Array.IndexOf(p.DeleteOrder,child.Key)<Array.IndexOf(p.DeleteOrder,parent.Key));return Task.CompletedTask;
        });
        await Test("Protected external FK to a seeded row blocks deletion",dir=>{
            var b=Base();var external=new Row("dbo.external",new(){["id"]="1"},new(){["id"]="1",["user_id"]="357"},"protected");b=b with{Rows=new(b.Rows){[external.Key]=external}};var user=Row("dbo.users",357,"owned");var c=b with{Rows=new(b.Rows){[user.Key]=user},ForeignKeys=[new("externalFK","dbo.external","dbo.users",["user_id"],["user_id"],false,false,"CASCADE")]};Check(Graph.Prove(b,c,new HashSet<string>{user.Key},[],new HashSet<long>()).Problems.Any(p=>p.StartsWith("EXTERNAL_FK_TO_OWNED")));return Task.CompletedTask;
        });
        await Test("External polymorphic audit targeting owned user blocks deletion",dir=>{var b=Base();var audit=new Row("dbo.audit_logs",new(){["audit_id"]="1"},new(){["entity_type"]="USER",["entity_id"]="357",["actor_user_id"]="999"},"external");b=b with{Rows=new(b.Rows){[audit.Key]=audit}};var c=Current() with{Rows=new(b.Rows){[Row("dbo.users",357,"owned").Key]=Row("dbo.users",357,"owned")}};Check(Graph.Prove(b,c,new HashSet<string>{Row("dbo.users",357,"owned").Key},[],new HashSet<long>{357}).Problems.Any(p=>p.StartsWith("EXTERNAL_POLYMORPHIC_REFERENCE")));return Task.CompletedTask;});
        await Test("Untrusted actual FK and owned FK cycle fail closed",dir=>{var b=Base();var c=Current() with{ForeignKeys=[new("bad","dbo.users","dbo.users",["user_id"],["user_id"],false,true,"NO_ACTION")]};Check(Graph.Prove(b,c,new HashSet<string>{Row("dbo.users",357,"owned").Key},[],new HashSet<long>()).Problems.Contains("UNTRUSTED_FK:bad"));var p1=Row("dbo.users",357,"a");var p2=Row("dbo.users",358,"b");p1.Values["parent_id"]="358";p2.Values["parent_id"]="357";c=b with{Rows=new(b.Rows){[p1.Key]=p1,[p2.Key]=p2},ForeignKeys=[new("cycle","dbo.users","dbo.users",["parent_id"],["user_id"],false,false,"NO_ACTION")]};Check(Graph.Prove(b,c,new HashSet<string>{p1.Key,p2.Key},[],new HashSet<long>()).Problems.Contains("OWNED_FK_CYCLE"));return Task.CompletedTask;});
        await Test("Interactive HTTP root requires independent CREATE audit and private lineage",dir=>{
            var b=Base();var branch=new Row("dbo.branches",new(){["branch_id"]="115"},new(){["branch_id"]="115"},"branch");var actor=Row("dbo.users",357,"actor");var incident=new Row("dbo.incidents",new(){["incident_id"]="901"},new(){["incident_id"]="901",["branch_id"]="115",["reported_by"]="357"},"incident");var audit=new Row("dbo.audit_logs",new(){["audit_id"]="99"},new(){["entity_type"]="INCIDENT",["entity_id"]="901",["actor_user_id"]="357",["action"]="CREATE"},"audit");var c=b with{Tables=[..b.Tables,new("dbo.branches",[new("branch_id","bigint",1)]),new("dbo.incidents",[new("incident_id","bigint",1)]),new("dbo.audit_logs",[new("audit_id","bigint",1)])],Rows=new(b.Rows){[branch.Key]=branch,[actor.Key]=actor,[incident.Key]=incident,[audit.Key]=audit}};var seed=new HashSet<string>{branch.Key,actor.Key};var root=new RootProof("dbo.incidents",incident.Pk,357,"POST","/api/incidents",201);Check(Graph.Prove(b,c,seed,[root],new HashSet<long>{357}).Problems.Length==0);c.Rows.Remove(audit.Key);Check(Graph.Prove(b,c,seed,[root],new HashSet<long>{357}).Problems.Any(p=>p.StartsWith("ACTION_CREATE_AUDIT_PROOF_MISSING")));return Task.CompletedTask;
        });
        await Durable.File(Path.Combine(output,"OFFLINE_RESULTS.json"),new{status=fail==0?"PASS_OFFLINE_ONLY":"FAIL",cases=count,pass=count-fail,fail,results=cases,sqlConnections=0,sqlMutations=0,realSqlOrBrowserAcceptance="NOT_RUN",processStarts=0});
        Console.WriteLine(JsonSerializer.Serialize(new{cases=count,pass=count-fail,fail,sqlConnections=0}));if(fail>0)Environment.ExitCode=1;
    }
}
